def _cand_beta_1(seq):
    if not seq:
        return []
    out = []
    run_len = 1
    for i in range(1, len(seq) + 1):
        if i < len(seq) and seq[i] % 2 == seq[i - 1] % 2:
            run_len += 1
        else:
            out.append(seq[i - 1] + 4 * run_len - 1)
            run_len = 1
    return out

