    if not seq:
        return []
    left = 0
    right = len(seq) - 1
    toggle = 1
    out = []
    while left <= right:
        if toggle == 1:
            out.append(seq[left] + 4)
            left += 1
        else:
            out.append(seq[right] - 2)
            right -= 1
        toggle = -toggle
    return out

